SELECT Имена_станций.NAME, Имена_ОЭС.abbr AS oesname, Имена_областей.abbr AS oblname, Имена_станций.ordnumb, Станции2006.YEAR, Станции2006.NUST, Станции2006.E, Станции2006.EOTP, Станции2006.EURT, Станции2006.EUST, Станции2006.Q, Станции2006.TURT, Станции2006.TUST, Станции2006.B, Станции2006.GAZ, Доп_угли2006.gazpp, Станции2006.MAZUT, Станции2006.TORF, Станции2006.SLAN, Станции2006.GTT, Станции2006.PROCH, Станции2006.UGOL, Станции2006.DON, Станции2006.PODM, Станции2006.PECH, Доп_угли2006.int, Доп_угли2006.vork, Станции2006.ARKT, Станции2006.KUZN, Станции2006.URAL, Доп_угли2006.sver, Доп_угли2006.chel, Доп_угли2006.kizel, Станции2006.BASHK, Станции2006.EKIB, Станции2006.KARAG, Станции2006.KAN, Доп_угли2006.nazar, Доп_угли2006.ibor, Доп_угли2006.berez, Доп_угли2006.per, Станции2006.IRKUT, Доп_угли2006.azey, Доп_угли2006.cher, Доп_угли2006.jer, Станции2006.HAK, Станции2006.TUV, Станции2006.BUR, Доп_угли2006.gusin, Доп_угли2006.tugn, Станции2006.CHIT, Доп_угли2006.har, Доп_угли2006.urt, Станции2006.[YAKUT] AS Выражение1, Станции2006.[AMUR] AS Выражение2, Станции2006.URG, Станции2006.PRIM, Станции2006.LUCH, Станции2006.MAG, Станции2006.SAH, Станции2006.USHUM, Станции2006.QOTR, Станции2006.SNK, Станции2006.EWTP, Станции2006.NT, Станции2006.OBOR, Станции2006.VED, Станции2006.OBL, Станции2006.DEP, Станции2006.OES, Станции2006.ER, Станции2006.NUMB1120, Имена_станций.Ведомство AS вед, IIf([ved]=1 Or [ved]=4,1,IIf([ved]=2 Or [ved]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group], Имена_станций.FO, Имена_станций.форэм, Станции2006.NTsum, Станции2006.GK, Станции2006.BE, имена_ГК.name AS namegk
FROM ((((Станции2006 INNER JOIN Имена_станций ON Станции2006.NUMB1120=Имена_станций.NUMB) INNER JOIN Имена_ОЭС ON Станции2006.OES=Имена_ОЭС.oes) INNER JOIN Имена_областей ON Станции2006.OBL=Имена_областей.OBL) LEFT JOIN Доп_угли2006 ON (Станции2006.NUMB1120=Доп_угли2006.NUMB1120) AND (Станции2006.YEAR=Доп_угли2006.YEAR)) LEFT JOIN имена_ГК ON Станции2006.GK=имена_ГК.code;
